'use strict';
let memberData,memberCsrf='',memberBusiness='',memberStatus='Open';
const escapeWork=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
async function workRequest(path,method='GET',data){const res=await fetch('/api/'+path,{method,headers:method==='GET'?{}:{'Content-Type':'application/json','X-Grow-Token':memberCsrf},body:data===undefined?undefined:JSON.stringify(data)});if(res.status===401){location.replace('/login');throw new Error('Sign in again.');}const value=await res.json();if(!res.ok)throw new Error(value.error||'Could not save.');return value;}
function workError(error){const el=document.querySelector('#work-error');el.textContent=error.message;el.hidden=false;}
async function refreshWork(){const state=await workRequest('state');memberData=state.data;memberCsrf=state.csrf;renderWork();}
function workLink(url,label){try{const parsed=new URL(url);if(!['http:','https:'].includes(parsed.protocol))return '';return `<a class="btn secondary compact" href="${escapeWork(url)}" target="_blank" rel="noopener noreferrer">${escapeWork(label)}</a>`;}catch{return '';}}
function renderWork(){const d=memberData,tasks=d.tasks.filter(t=>(!memberBusiness||t.business_id===memberBusiness)&&(memberStatus==='All'||(memberStatus==='Open'?t.status!=='Done':t.status==='Done')));document.querySelector('#work').innerHTML=`<div class="page-heading"><div><p class="eyebrow">GROW / MY WORK</p><h1>Hello, ${escapeWork(d.person.name)}.</h1><p class="route-intro">Your assigned work across ${d.businesses.length} businesses.</p></div><button class="btn secondary" data-work-action="logout">Sign out</button></div><div class="toolbar"><select id="work-business" aria-label="Business"><option value="">All my businesses</option>${d.businesses.map(b=>`<option value="${escapeWork(b.id)}" ${memberBusiness===b.id?'selected':''}>${escapeWork(b.name)}</option>`).join('')}</select><select id="work-status" aria-label="Task filter">${['Open','Done','All'].map(s=>`<option ${s===memberStatus?'selected':''}>${s}</option>`).join('')}</select><button class="btn secondary" data-work-action="refresh">Refresh</button></div><div class="member-grid">${tasks.map(t=>{const steps=d.task_steps.filter(s=>s.task_id===t.id),content=d.content.find(c=>c.id===t.content_id),link=d.business_links.find(l=>l.id===t.business_link_id);return `<article class="card member-task"><p class="eyebrow">${escapeWork(d.businesses.find(b=>b.id===t.business_id)?.name)}${t.client_id?' / '+escapeWork(d.clients.find(c=>c.id===t.client_id)?.name):''}</p><h2>${escapeWork(t.title)}</h2><p class="muted">${escapeWork(t.priority)} priority · Due ${escapeWork(t.due||'not set')}</p><p class="member-text">${escapeWork(t.notes)}</p><label>Status<select data-work-task="${escapeWork(t.id)}">${['Open','In progress','Blocked','Done'].map(s=>`<option ${s===t.status?'selected':''}>${s}</option>`).join('')}</select></label>${steps.map(s=>`<label class="checklist-step"><input type="checkbox" data-work-step="${escapeWork(s.id)}" ${s.completed?'checked':''}><span>${escapeWork(s.title)}</span></label>`).join('')}<form data-work-checklist="${escapeWork(t.id)}"><input name="title" placeholder="Add a checklist step" maxlength="300" required><button class="btn secondary compact">Add step</button></form><form data-work-note="${escapeWork(t.id)}"><label>Progress note<textarea name="progress_note" maxlength="10000" rows="3">${escapeWork(t.progress_note)}</textarea></label><button class="btn secondary compact">Save progress</button></form>${workLink(t.url,'Open work link')}${link?workLink(link.url,link.title):''}${content?`<details><summary>Content brief: ${escapeWork(content.title)}</summary><p class="member-text">${escapeWork(content.copy)}</p>${workLink(content.asset_url,'Open creative asset')}</details>`:''}</article>`;}).join('')||'<div class="empty"><h2>No assigned tasks here yet.</h2><p>Your tasks appear when the owner assigns them to you.</p></div>'}</div>`;}
document.addEventListener('change',async e=>{try{if(e.target.id==='work-business'){memberBusiness=e.target.value;renderWork();}if(e.target.id==='work-status'){memberStatus=e.target.value;renderWork();}if(e.target.dataset.workTask){await workRequest('tasks/'+e.target.dataset.workTask,'PATCH',{status:e.target.value});await refreshWork();}if(e.target.dataset.workStep){await workRequest('task_steps/'+e.target.dataset.workStep,'PATCH',{completed:e.target.checked});await refreshWork();}}catch(error){workError(error);}});
document.addEventListener('submit',async e=>{const form=e.target;if(!form.dataset.workNote&&!form.dataset.workChecklist)return;e.preventDefault();try{if(form.dataset.workNote)await workRequest('tasks/'+form.dataset.workNote,'PATCH',{progress_note:form.progress_note.value});else await workRequest('task_steps','POST',{task_id:form.dataset.workChecklist,title:form.title.value,completed:false});await refreshWork();}catch(error){workError(error);}});
document.addEventListener('click',async e=>{const action=e.target.closest('[data-work-action]')?.dataset.workAction;if(!action)return;try{if(action==='logout'){await workRequest('logout','POST',{});location.replace('/login');}else await refreshWork();}catch(error){workError(error);}});
refreshWork().catch(workError);
